llm.raw_content:
{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C38"],
      "claim": "Tetrabenazine, which shares the same 9,10-dimethoxy-benzoquinolizine core as the query, has a very low mean oral systemic availability of 0.049 ± 0.032 in patients, with individual values ranging from 0.001 to 0.085.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C29"],
      "claim": "Valbenazine, a benzoquinolizine prodrug of dihydrotetrabenazine, has an absolute oral bioavailability of approximately 49% in humans, showing that the core can achieve moderate F only when the metabolic liability is masked by prodrug design.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C62"],
      "claim": "Almorexant, a structurally related dimethoxyphenyl basic amine, has a low absolute oral bioavailability of 11.2% in healthy subjects, consistent with extensive first-pass metabolism in this chemotype.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is a tetrabenazine analogue with a dimethylaminopropyl side chain and a lactam in the benzoquinolizine core. The most transferable direct evidence is tetrabenazine's very low oral bioavailability (mean ~5%, all values <10%), indicating extensive first-pass metabolism of this core. Valbenazine's higher F (~49%) is less applicable because it is a prodrug that masks the metabolic liability, whereas the query is not a prodrug. Weaker evidence from almorexant and verapamil also leans low, while donepezil, urapidil, and gallopamil are structurally too distant to override the core-based negative signal. Therefore, F is predicted below 20%.",
  "evidence_gaps": [
    "No direct experimental bioavailability data exist for the exact query molecule.",
    "The effect of the dimethylaminopropyl side chain and lactam on the metabolic stability of the benzoquinolizine core is uncertain.",
    "Valbenazine's high F is from a prodrug, so its relevance to the non-prodrug query is limited."
  ],
  "new_evidence_assessment": [
    {
      "applicability": "high",
      "card_ids": ["C38"],
      "decision_effect": "strengthened",
      "direction": "supportive",
      "family": "tetrabenazine"
    },
    {
      "applicability": "high",
      "card_ids": ["C29"],
      "decision_effect": "weakened",
      "direction": "contradictory",
      "family": "valbenazine"
    },
    {
      "applicability": "moderate",
      "card_ids": ["C62"],
      "decision_effect": "strengthened",
      "direction": "supportive",
      "family": "almorexant"
    }
  ],
  "revision_action": "initial"
}

